import React, { useState, useMemo, useRef, useEffect } from 'react';
import styles from './index.module.scss';

// 退出动画时长（ms），需与 index.module.scss 中 $dialog-exit-duration 保持一致
const EXIT_ANIMATION_DURATION = 240;

export interface DialogOption {
  text: string;
  onClick: () => void;
}

export interface StardewDialogProps {
  /** 对话内容（字符串或字符串数组） */
  content: string | string[];
  /** 说话人图片 URL */
  speakerImage?: string;
  /** 说话人名称 */
  speaker?: string;
  /** 确定按钮文字，不传则不显示 */
  okText?: string;
  /** 取消按钮文字，不传则不显示 */
  cancelText?: string;
  /** 确定按钮点击事件 */
  onOk?: () => void;
  /** 取消按钮点击事件 */
  onCancel?: () => void;
  /** 点击空白区域关闭回调 */
  onClose?: () => void;
  /** 是否显示对话框 */
  visible: boolean;
  /** 每屏最大字符数（默认 120 字符） */
  maxCharsPerPage?: number;
  /** 内容超出时是否启用多步骤 */
  enableMultiStep?: boolean;
}

/**
 * 星露谷风格对话框组件
 * 使用 dialogBg.png 作为背景
 * 支持多步骤显示：当内容超出高度时，点击屏幕任意地方显示下一页
 */
const StardewDialog: React.FC<StardewDialogProps> = ({
  content,
  speakerImage,
  speaker,
  okText = '确定',
  cancelText = '取消',
  onOk,
  onCancel,
  onClose,
  visible,
  maxCharsPerPage = 120,
  enableMultiStep = true,
}) => {
  const [currentPage, setCurrentPage] = useState(0);
  const contentRef = useRef<HTMLDivElement>(null);

  // 出入场动画：visible 卸载前先播放退出动画
  // mounted 决定是否渲染 DOM，closing 决定播放哪段动画
  const [animationState, setAnimationState] = useState({
    visible,
    mounted: visible,
    closing: false,
  });

  if (visible !== animationState.visible) {
    setAnimationState({
      visible,
      mounted: visible ? true : animationState.mounted,
      closing: !visible && animationState.mounted,
    });
  }

  useEffect(() => {
    if (!animationState.closing) return;
    const timer = setTimeout(() => {
      setAnimationState((prev) => ({ ...prev, mounted: false, closing: false }));
    }, EXIT_ANIMATION_DURATION);
    return () => clearTimeout(timer);
  }, [animationState.closing]);

  const pages = useMemo(() => {
    if (Array.isArray(content)) {
      return content;
    }
    
    if (!enableMultiStep) {
      return [content];
    }

    const result: string[] = [];
    let currentContent = content;
    
    while (currentContent.length > 0) {
      if (currentContent.length <= maxCharsPerPage) {
        result.push(currentContent);
        break;
      }
      
      let breakPoint = maxCharsPerPage;
      const lastSpace = currentContent.lastIndexOf(' ', maxCharsPerPage);
      const lastPunctuation = currentContent.search(/(?<=.{80,}[,.!?.,!?])/);
      
      if (lastSpace > maxCharsPerPage * 0.8 && lastSpace > lastPunctuation) {
        breakPoint = lastSpace;
      } else if (lastPunctuation > maxCharsPerPage * 0.8) {
        breakPoint = lastPunctuation + 1;
      }
      
      result.push(currentContent.substring(0, breakPoint).trim());
      currentContent = currentContent.substring(breakPoint).trim();
    }
    
    return result.length > 0 ? result : [content];
  }, [content, maxCharsPerPage, enableMultiStep]);

  const [prevPages, setPrevPages] = useState(pages);
  const [prevVisible, setPrevVisible] = useState(visible);

  if (pages !== prevPages || visible !== prevVisible) {
    setPrevPages(pages);
    setPrevVisible(visible);
    setCurrentPage(0);
  }

  const totalPages = pages.length;

  if (!animationState.mounted) return null;

  // 判断是否是多步骤模式且有多个页面
  const hasMultiplePages = pages.length > 1;

  // 判断是否是最后一页
  const isLastPage = currentPage >= totalPages - 1;

  // 处理点击对话框（多步骤模式下切换到下一页）
  const handleDialogClick = (e: React.MouseEvent<HTMLDivElement>) => {
    // 如果点击的是按钮，不触发跳转
    if ((e.target as HTMLElement).tagName === 'BUTTON') {
      return;
    }
    
    if (hasMultiplePages && !isLastPage) {
      // 还有下一页，切换到下一页
      setCurrentPage(prev => prev + 1);
    } else if (isLastPage && onClose) {
      // 已经是最后一页，关闭对话框
      onClose();
    }
  };

  // 处理确定按钮
  const handleOk = () => {
    if (hasMultiplePages && !isLastPage) {
      // 还有下一页
      setCurrentPage(prev => prev + 1);
    } else if (onOk) {
      // 最后一页，执行确定操作
      onOk();
    }
  };

  // 处理取消按钮
  const handleCancel = () => {
    if (onCancel) {
      onCancel();
    }
  };

  return (
    <div className={`${styles.dialogOverlay} ${animationState.closing ? styles.overlayClosing : ''}`}>
      <div
        className={`${styles.dialogContainer} ${animationState.closing ? styles.containerClosing : ''}`}
        onClick={handleDialogClick}
      >
        {/* 左侧对话内容区域 */}
        <div className={styles.contentSection}>
          <div className={styles.contentText} ref={contentRef}>
            {pages[currentPage]}
          </div>
          
          {/* 页码指示器 */}
          {totalPages > 1 && (
            <div className={styles.pageIndicator}>
              <span>{currentPage + 1} / {totalPages}</span>
            </div>
          )}
        </div>

        {/* 右侧说话人区域 */}
        <div className={styles.speakerSection}>
          {/* 说话人图片 */}
          <div className={styles.speakerImageWrapper}>
            {speakerImage ? (
              <img src={speakerImage} alt={speaker || 'speaker'} className={styles.speakerImage} />
            ) : (
              <div className={styles.speakerPlaceholder} />
            )}
          </div>

          {/* 说话人名称 */}
          {speaker && (
            <div className={styles.speakerNameWrapper}>
              <span className={styles.speakerName}>{speaker}</span>
            </div>
          )}
        </div>

        {/* 底部按钮区域 - 只在最后一页显示 */}
        {isLastPage && (
          <div className={styles.buttonSection}>
            {onCancel && (
              <button className={`${styles.dialogButton} ${styles.cancelButton}`} onClick={handleCancel}>
                {cancelText}
              </button>
            )}
            {onOk && (
              <button className={`${styles.dialogButton} ${styles.okButton}`} onClick={handleOk}>
                {okText}
              </button>
            )}
          </div>
        )}
        
        {/* 非最后一页时显示继续提示 */}
        {!isLastPage && hasMultiplePages && (
          <div className={styles.continueHint}>
            <span>点击继续</span>
          </div>
        )}
      </div>
    </div>
  );
};

export default StardewDialog;
