import { useEffect, Suspense } from 'react';
import { RouterProvider } from 'react-router-dom';
import { ConfigProvider, App as AntdApp } from 'antd';
import zhCN from 'antd/locale/zh_CN';
import { AuthProvider } from './hooks/useAuth';
import { PWAInstallPrompt } from './components/PWAInstallPrompt';
import OfflineIndicator from './components/OfflineIndicator';
import { themeManager } from './utils/theme';
import { initializeDataStore } from './utils/dataMigration';
import { requestPersistentStorage } from './utils/storageGuard';
import LoadingScreen from './components/LoadingScreen';
import router, { preloadRoutes } from './router';
import './App.module.scss';

const theme = {
  token: {
    colorPrimary: '#8B5A2B',
    colorSuccess: '#4a9c3d',
    colorWarning: '#e8a838',
    colorError: '#c45c48',
    colorInfo: '#6b9dc7',
    borderRadius: 8,
    fontSize: 14,
    colorBgBase: '#f5e8c7',
    colorTextBase: '#3c2f1f',
  },
  components: {
    Button: {
      borderRadius: 8,
    },
    Input: {
      borderRadius: 8,
    },
    Tag: {
      borderRadius: 12,
    },
    Card: {
      borderRadius: 12,
    },
    Modal: {
      borderRadius: 16,
    },
  },
};

const getPopupContainer = () => {
  const phoneContent = document.querySelector('[data-phone-content]');
  if (phoneContent) return phoneContent as HTMLElement;
  return document.body;
};

// 静态方法（Modal.confirm/message/notification）无法消费组件内 Context，
// 通过 holderRender 让它们也渲染进手机内容区并继承主题/语言，
// 否则 fixed 定位会覆盖整个浏览器视口，脱离手机框
ConfigProvider.config({
  holderRender: (node) => (
    <ConfigProvider locale={zhCN} theme={theme} getPopupContainer={getPopupContainer}>
      <AntdApp>{node}</AntdApp>
    </ConfigProvider>
  ),
});

function App() {
  useEffect(() => {
    void initializeDataStore();
    void requestPersistentStorage(); // 申请持久化存储授权，防浏览器自动清除
    // 首屏稳定后预热全部路由 chunk，点击 tab/导航零等待（跟手）
    const preloadTimer = setTimeout(() => preloadRoutes(), 1500);
    return () => clearTimeout(preloadTimer);
  }, []);

  useEffect(() => {
    const unsubscribe = themeManager.subscribe(() => {});
    return () => unsubscribe();
  }, []);

  return (
    <ConfigProvider locale={zhCN} theme={theme} getPopupContainer={getPopupContainer}>
      <AntdApp>
        <AuthProvider>
          <Suspense fallback={<LoadingScreen />}>
            <RouterProvider router={router} />
          </Suspense>
          <OfflineIndicator />
          <PWAInstallPrompt />
        </AuthProvider>
      </AntdApp>
    </ConfigProvider>
  );
}

export default App;
